INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Finanzierungsmodelle > Miete, Leasing, Kauf
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Miete eines IT-Systems immer günstiger als der Kauf?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Nutzungsdauer und Kosten"}, {"text": "Ja", "correct": false, "because": "Nicht pauschal günstiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Leasing die Liquidität eines Unternehmens schonen?', 2, '[{"text": "Ja", "correct": true, "because": "Keine hohen Anfangsinvestitionen nötig"}, {"text": "Nein", "correct": false, "because": "Liquidität wird geschont"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Kauf eines IT-Systems immer mit einem Eigentumsübergang verbunden?', 2, '[{"text": "Ja", "correct": true, "because": "Kauf bedeutet Eigentumserwerb"}, {"text": "Nein", "correct": false, "because": "Eigentum ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Mietverträge für IT-Systeme ohne festgelegte Laufzeit abgeschlossen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Laufzeit ist vertraglich festgelegt"}, {"text": "Ja", "correct": false, "because": "Verträge haben Laufzeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Leasing immer mit einem Rückgaberecht verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Vertragstyp"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend Rückgabe"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Finanzierungsmodell schont die Liquidität am meisten?', 3, '[{"text": "Leasing", "correct": true, "because": "Verteilt Kosten über Zeit"}, {"text": "Kauf", "correct": false, "because": "Hohe Einmalzahlung"}, {"text": "Miete", "correct": false, "because": "Laufende Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Modell bietet Eigentum am IT-System?', 2, '[{"text": "Kauf", "correct": true, "because": "Eigentumserwerb"}, {"text": "Miete", "correct": false, "because": "Kein Eigentum"}, {"text": "Leasing", "correct": false, "because": "Meist kein Eigentum"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart ist typisch für die Miete eines IT-Systems?', 2, '[{"text": "Monatliche Mietzahlungen", "correct": true, "because": "Regelmäßige Zahlungen"}, {"text": "Einmalige Anschaffung", "correct": false, "because": "Kauf"}, {"text": "Wartungskosten", "correct": false, "because": "Separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ist beim Leasing von IT-Systemen entscheidend?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Ermöglicht Austausch nach Vertragsende"}, {"text": "Geringe Anfangskosten", "correct": false, "because": "Auch wichtig"}, {"text": "Eigentum", "correct": false, "because": "Nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel des Kaufs eines IT-Systems?', 2, '[{"text": "Langfristige Nutzung", "correct": true, "because": "Eigentum für Dauerbetrieb"}, {"text": "Kurzfristige Flexibilität", "correct": false, "because": "Miete/Leasing"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Miete von IT-Systemen?', 4, '[{"text": "Kurzfristige Nutzung", "correct": true, "because": "Flexibel einsetzbar"}, {"text": "Keine Wartungspflicht", "correct": true, "because": "Oft beim Vermieter"}, {"text": "Geringe Anfangskosten", "correct": true, "because": "Keine hohe Investition"}, {"text": "Eigentumserwerb", "correct": false, "because": "Nicht bei Miete"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale charakterisieren Leasing von IT-Systemen?', 3, '[{"text": "Zeitlich befristet", "correct": true, "because": "Vertragslaufzeit"}, {"text": "Kostenschonend", "correct": true, "because": "Verteilt Zahlungen"}, {"text": "Option auf Kauf", "correct": true, "because": "Manchmal möglich"}, {"text": "Hohe Einmalzahlung", "correct": false, "because": "Nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können beim Kauf eines IT-Systems auftreten?', 3, '[{"text": "Hohe Anfangskosten", "correct": true, "because": "Einmalige Investition"}, {"text": "Technologische Veralterung", "correct": true, "because": "Langfristiges Risiko"}, {"text": "Wartungsverantwortung", "correct": true, "because": "Beim Eigentümer"}, {"text": "Kurzfristige Flexibilität", "correct": false, "because": "Nicht beim Kauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Wahl zwischen Miete, Leasing und Kauf?', 4, '[{"text": "Budget", "correct": true, "because": "Finanzielle Möglichkeiten"}, {"text": "Nutzungsdauer", "correct": true, "because": "Kurz- oder Langfristigkeit"}, {"text": "Flexibilität", "correct": true, "because": "Anpassungsbedarf"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten fallen bei den Finanzierungsmodellen an?', 3, '[{"text": "Mietzahlungen", "correct": true, "because": "Bei Miete"}, {"text": "Leasingraten", "correct": true, "because": "Bei Leasing"}, {"text": "Anschaffungskosten", "correct": true, "because": "Beim Kauf"}, {"text": "Lieferkosten", "correct": false, "because": "Logistisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Miete bietet Flexibilität bei kurzfristiger Nutzung. b) Kauf schont immer die Liquidität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Miete flexibel, Kauf belastet Liquidität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Leasing verteilt Kosten über die Zeit. b) Miete führt immer zum Eigentum.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leasing ja, Miete kein Eigentum"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kauf bedeutet Eigentum am IT-System. b) Leasingverträge sind immer ohne Laufzeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kauf ja, Leasing mit Laufzeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Mietzahlungen sind regelmäßige Kosten. b) Kauf ist immer die günstigste Option.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Miete ja, Kauf abhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Leasing bietet Flexibilität bei Technologieupdates. b) Eigentum ist bei Leasing immer enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, Eigentum nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

